#include <cassert>
#include <iostream>
#include <optional>
#include <variant>

struct Damage { int amount; };
struct Heal { int amount; };
struct Shield { int amount; };
using Effect = std::variant<Damage, Heal, Shield>;

std::optional<Effect> reward(bool found) {
    if (!found) return std::nullopt;
    return Effect{Damage{300}};
}

int main() {
    auto result = reward(true);
    assert(result.has_value());
    std::visit([](const auto& effect) {
        std::cout << effect.amount << '\n';
    }, *result);
    assert(!reward(false).has_value());
}

#include <cassert>
#include <concepts>

template<class T>
concept DamageSpell = requires(const T& spell) {
    { spell.damage() } -> std::same_as<int>;
    { spell.cost() } -> std::same_as<int>;
};

struct Ember {
    int damage() const { return 200; }
    int cost() const { return 2; }
};
struct HealingSpell {
    int heal() const { return 100; }
};

template<DamageSpell T>
int cast(const T& spell, int pips) {
    if (pips < spell.cost()) return 0;
    return spell.damage();
}

int main() {
    static_assert(DamageSpell<Ember>);
    static_assert(!DamageSpell<HealingSpell>);
    assert(cast(Ember{}, 2) == 200);
    assert(cast(Ember{}, 1) == 0);
    // cast(HealingSpell{}, 2); // Rejected by the constraint
}

#include <array>
#include <cassert>
#include <iostream>
#include <ranges>
#include <string_view>

struct Spell {
    std::string_view name;
    int cost;
    bool damaging;
};

int main() {
    std::array<Spell, 3> deck{{
        {"Ember", 2, true},
        {"Ward", 1, false},
        {"Thunder", 5, true}
    }};
    int pips = 3;
    auto names = deck
        | std::views::filter([pips](const Spell& spell) {
              return spell.damaging && spell.cost <= pips;
          })
        | std::views::transform(&Spell::name);

    int count = 0;
    for (std::string_view name : names) {
        std::cout << name << '\n';
        ++count;
    }
    assert(count == 1);
}

