constexpr int damage(int base, int bonus) {
    return base + bonus;
}
constexpr int hit = damage(200, 50);
static_assert(hit == 250, "damage total");
int main() {}

constexpr int total_cost(const int* costs, int count) {
    int total = 0;
    for (int i = 0; i < count; ++i) total += costs[i];
    return total;
}
constexpr int costs[] = {1, 2, 3};
static_assert(total_cost(costs, 3) == 6, "deck cost");
int main() {}

#include <type_traits>

struct Damage { int amount; };
struct Shield { int strength; };

template<class T>
constexpr int damage_value(const T& effect) {
    if constexpr (std::is_same_v<T, Damage>) {
        return effect.amount;
    } else {
        return 0;
    }
}
static_assert(damage_value(Damage{200}) == 200);
static_assert(damage_value(Shield{50}) == 0);
int main() {}

consteval int checked_cost(int cost) {
    if (cost < 0) throw "negative cost";
    return cost;
}
constexpr int cost = checked_cost(2);
static_assert(cost == 2);
// int bad = checked_cost(-1); // Not a constant expression
int main() {}

#include <cassert>

consteval int compile_time_double(int value) {
    return value * 2;
}

constexpr int doubled_damage(int value) {
    if consteval {
        return compile_time_double(value);
    } else {
        return value + value;
    }
}

static_assert(doubled_damage(100) == 200);
int main() {
    int base = 100;
    assert(doubled_damage(base) == 200);
}
